Object.assign(SNIP,{});PRESET_NOTES["l18"]={"Ví dụ: Kiểm tra dấu ngoặc": "Phần {[()()]} đúng, nhưng dấu ( cuối cùng không có ngoặc đóng: stack còn một phần tử nên in NO.", "Ví dụ: Phần tử nhỏ hơn gần nhất bên trái": "Đáp án 0 1 0 3 4 3 3 7: ví dụ phần tử 3 (vị trí 6) có gần nhất bên trái nhỏ hơn là 1 ở vị trí 3. Phần tử 4 và 8 bị bỏ khỏi stack khi gặp 3 vì chúng không còn là đáp án cho ai ở sau.", "Ví dụ: Max trên cửa sổ trượt": "Kết quả 3 3 5 5 6 7. Đầu deque luôn là chỉ số của max trong cửa sổ; phần tử nhỏ hơn đứng trước một phần tử lớn hơn thì vô dụng và bị bỏ."};EX_HINTS["l18"]=[["Code mẫu đúng nhưng xóa từng cặp rồi quét lại từ đầu: O(n²).", "Gặp ngoặc mở thì push; gặp ngoặc đóng thì đỉnh stack phải là ngoặc mở cùng loại.", "Cuối cùng stack phải rỗng. Kiểm tra empty() trước khi top()."], ["Code mẫu nhìn sang trái từng phần tử: dãy giảm dần làm nó O(n²).", "Giữ stack chỉ số có giá trị tăng dần; bỏ mọi phần tử ≥ a[i] khỏi đỉnh, đỉnh còn lại là đáp án.", "Mỗi chỉ số vào và ra stack một lần: O(n)."], ["Code mẫu tính lại max cả cửa sổ: O(n · k).", "Deque giữ chỉ số có giá trị giảm dần: thêm i thì bỏ ở cuối mọi phần tử ≤ a[i]; bỏ ở đầu chỉ số ≤ i − k.", "Đầu deque là chỉ số của max cửa sổ hiện tại."]];
