const PR18=[{label:"Ví dụ: Kiểm tra dấu ngoặc",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    string s = \"{[()()]}(\";\n    stack<char> st;\n    bool ok = true;\n    for (char c : s) {\n        if (c == '(' || c == '[' || c == '{') st.push(c);\n        else {\n            if (st.empty()) { ok = false; break; }\n            char m = st.top();\n            st.pop();\n            if ((c == ')' && m != '(') || (c == ']' && m != '[') || (c == '}' && m != '{')) { ok = false; break; }\n        }\n    }\n    if (!st.empty()) ok = false;       // còn ngoặc mở chưa đóng\n    cout << (ok ? \"YES\" : \"NO\") << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"st"},{type:"vars",names:["c","ok"]}]},{label:"Ví dụ: Phần tử nhỏ hơn gần nhất bên trái",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<int> a = {2, 5, 1, 4, 8, 3, 2, 5};\n    int n = a.size();\n    vector<int> kq(n, 0);\n    stack<int> st;                      // chỉ số, giá trị tăng dần từ đáy lên đỉnh\n    for (int i = 0; i < n; i++) {\n        while (!st.empty() && a[st.top()] >= a[i]) st.pop();\n        kq[i] = st.empty() ? 0 : st.top() + 1;   // vị trí đánh số từ 1, 0 = không có\n        st.push(i);\n    }\n    for (int x : kq) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]},{type:"cont",of:"st"},{type:"cells",of:"kq"}]},{label:"Ví dụ: Max trên cửa sổ trượt",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<int> a = {1, 3, -1, -3, 5, 3, 6, 7};\n    int n = a.size(), k = 3;\n    deque<int> dq;                      // chỉ số, giá trị giảm dần từ đầu tới cuối\n    for (int i = 0; i < n; i++) {\n        while (!dq.empty() && a[dq.back()] <= a[i]) dq.pop_back();\n        dq.push_back(i);\n        if (dq.front() <= i - k) dq.pop_front();   // đã ra khỏi cửa sổ\n        if (i >= k - 1) cout << a[dq.front()] << \" \";\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]},{type:"cont",of:"dq"}]}];
