makeEx2(document.getElementById("ex-l18"),sim18,[{t:"Dấu ngoặc",d:"File NGOAC.INP chứa một xâu s gồm các ký tự ( ) [ ] { } (1 ≤ |s| ≤ 10⁶). Ghi vào NGOAC.OUT YES nếu s là dãy ngoặc đúng, ngược lại NO.",tests:[{in:"{[()()]}",out:"YES"},{in:"([)]",out:"NO"},{in:"(",out:"NO"},{in:")(",out:"NO"},{in:"()[]{}",out:"YES"},{in:"()[]({})[()[(())]{[]}][]{}[{}]{}(){()()[]{}{}{()}}({}{}{{}})",out:"YES"},{in:"((()()){(){}}{{}{{({{}[]}[()({[]})])}}}))",out:"NO"},{in:"(((((((((())))))))))",out:"YES"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"NGOAC.INP\", \"r\")) {\n        freopen(\"NGOAC.INP\", \"r\", stdin);\n        freopen(\"NGOAC.OUT\", \"w\", stdout);\n    }\n    string s;\n    cin >> s;\n    // xóa lặp lại các cặp kề nhau (), [], {} cho tới khi không xóa được\n    bool doi = true;\n    while (doi) {\n        doi = false;\n        for (int i = 0; i + 1 < (int)s.size(); i++)\n            if ((s[i] == '(' && s[i + 1] == ')') || (s[i] == '[' && s[i + 1] == ']') || (s[i] == '{' && s[i + 1] == '}')) {\n                s.erase(i, 2);\n                doi = true;\n                break;\n            }\n    }\n    cout << (s.empty() ? \"YES\" : \"NO\") << \"\\n\";\n    return 0;\n}",file:"NGOAC",perf:{gen:n=>"(".repeat(n>>1)+")".repeat(n>>1),ns:[100,200,400],need:"n",limit:n=>80*n+500,why:"Xóa từng cặp rồi quét lại là O(n²). Stack duyệt một lần."}},{t:"Nhỏ hơn gần nhất",d:"File GANNHAT.INP: dòng 1 là n (1 ≤ n ≤ 2·10⁵); dòng 2 là n số nguyên (1 ≤ aᵢ ≤ 10⁹). Với mỗi i, tìm vị trí j &lt; i lớn nhất có aⱼ &lt; aᵢ (đánh số từ 1), hoặc 0 nếu không có. Ghi vào GANNHAT.OUT n số trên một dòng.",tests:[{in:"8\n2 5 1 4 8 3 2 5",out:"0 1 0 3 4 3 3 7"},{in:"1\n7",out:"0"},{in:"4\n1 2 3 4",out:"0 1 2 3"},{in:"4\n4 3 2 1",out:"0 0 0 0"},{in:"3\n3 3 3",out:"0 0 0"},{in:"50\n2 3 12 18 6 17 5 7 9 3 6 19 8 5 10 4 19 12 3 12 11 3 20 9 12 6 13 14 17 14 17 1 9 14 2 19 9 13 9 3 7 10 6 12 5 15 3 4 11 9",out:"0 1 2 3 2 5 2 7 8 1 10 11 11 10 14 10 16 16 1 19 19 1 22 22 24 22 26 27 28 27 30 0 32 33 32 35 35 37 35 35 40 41 40 43 40 45 35 47 48 48"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"GANNHAT.INP\", \"r\")) {\n        freopen(\"GANNHAT.INP\", \"r\", stdin);\n        freopen(\"GANNHAT.OUT\", \"w\", stdout);\n    }\n    int n;\n    cin >> n;\n    vector<int> a(n);\n    for (auto& x : a) cin >> x;\n    for (int i = 0; i < n; i++) {\n        int j = i - 1;\n        while (j >= 0 && a[j] >= a[i]) j--;     // nhìn sang trái từng phần tử\n        cout << j + 1 << (i + 1 < n ? \" \" : \"\\n\");\n    }\n    return 0;\n}",file:"GANNHAT",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>n-i).join(" "),ns:[200,800,3200],need:"n",limit:n=>80*n+500,why:"Nhìn sang trái từng phần tử là O(n²) với dãy giảm. Ngăn xếp đơn điệu là O(n)."}},{t:"Nhiệt độ cao nhất",d:"File NHIETDO.INP: dòng 1 là n, k (1 ≤ k ≤ n ≤ 2·10⁵); dòng 2 là n số nguyên (|aᵢ| ≤ 10⁹): nhiệt độ n ngày. Ghi vào NHIETDO.OUT n − k + 1 số trên một dòng: nhiệt độ cao nhất của mỗi đợt k ngày liên tiếp.",tests:[{in:"8 3\n1 3 -1 -3 5 3 6 7",out:"3 3 5 5 6 7"},{in:"1 1\n5",out:"5"},{in:"4 2\n4 3 2 1",out:"4 3 2"},{in:"4 4\n1 2 3 4",out:"4"},{in:"50 7\n49 21 49 9 17 23 -39 -22 40 -41 9 49 -10 -30 47 42 -39 -22 -4 18 31 12 17 48 14 49 -2 1 36 -11 8 46 -48 15 32 -26 34 -24 -48 -40 0 34 46 -4 41 -42 23 -49 -15 -23",out:"49 49 49 40 40 49 49 49 49 49 49 49 47 47 47 42 31 48 48 49 49 49 49 49 49 49 46 46 46 46 46 46 34 34 34 34 46 46 46 46 46 46 46 41"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"NHIETDO.INP\", \"r\")) {\n        freopen(\"NHIETDO.INP\", \"r\", stdin);\n        freopen(\"NHIETDO.OUT\", \"w\", stdout);\n    }\n    int n, k;\n    cin >> n >> k;\n    vector<long long> a(n);\n    for (auto& x : a) cin >> x;\n    for (int i = k - 1; i < n; i++) {\n        long long m = a[i];\n        for (int j = i - k + 1; j < i; j++) m = max(m, a[j]);\n        cout << m << (i + 1 < n ? \" \" : \"\\n\");\n    }\n    return 0;\n}",file:"NHIETDO",perf:{gen:n=>n+" "+(n>>1)+"\n"+Array.from({length:n},(_,i)=>n-i).join(" "),ns:[200,800,3200],need:"n",limit:n=>80*n+500,why:"Tính lại max mỗi cửa sổ là O(n · k). Hàng đợi đơn điệu là O(n)."}}]);

